import{c as s,$ as r,Q as t,j as i,g as a,o as e,n,m as c}from"./chunks/framework.Ce_49mA8.js";const k=JSON.parse('{"title":"Калькулятор и рецепты изделий","description":"Полное руководство по проектированию технологических карт, расчету себестоимости, накладных расходов и запуску партий в производство в ОмниКрафт ЕРП.","frontmatter":{"title":"Калькулятор и рецепты изделий","description":"Полное руководство по проектированию технологических карт, расчету себестоимости, накладных расходов и запуску партий в производство в ОмниКрафт ЕРП.","datePublished":"2026-11-15","dateModified":"2026-11-19","order":6},"headers":[],"relativePath":"ru/docs/spaces/production/calculator.md","filePath":"ru/docs/spaces/production/calculator.md","lastUpdated":1795046400000}'),d={name:"ru/docs/spaces/production/calculator.md"},g={id:"калькулятор-технологические-карты-и-себестоимость",tabindex:"-1"};function h(p,o,u,m,b,f){const l=r("DocIcon");return t(),i("div",null,[a("h1",g,[e(l,{name:"calculator"}),o[0]||(o[0]=n(" Калькулятор: Технологические карты и себестоимость ",-1)),o[1]||(o[1]=a("a",{class:"header-anchor",href:"#калькулятор-технологические-карты-и-себестоимость","aria-label":'Permalink to "Калькулятор: Технологические карты и себестоимость"'},"​",-1))]),o[2]||(o[2]=c('<p>В ремесленном деле и малом производстве самая опасная иллюзия — ощущение высокой прибыли, рассчитанной поспешно «в уме» лишь на основе стоимости израсходованного сырья. Когда создатель не учитывает стоимость собственного времени, амортизацию оборудования, брак при раскрое, комплектацию упаковки и постоянные издержки цеха, реальная экономика мастерской незаметно сползает в скрытый кассовый разрыв.</p><p>Вкладка <strong>«Калькулятор»</strong> в <strong>ОмниКрафт ЕРП</strong> служит главным инженерным и финансовым ядром предприятия. Здесь Вы проектируете цифровые технологические карты изделий, рассчитываете объективную себестоимость с учетом всех прямых и косвенных затрат, моделируете партии любого объема и передаете проверенные заказы на верстак в один клик.</p><div class="tip custom-block"><p class="custom-block-title">Полезный материал для разовых расчетов</p><p>Если Вам требуется быстро прикинуть формулу для единичного нестандартного заказа или скачать готовый шаблон расчетной таблицы, воспользуйтесь нашим <a href="/ru/calculators/product-cost-calculator">универсальным онлайн-калькулятором себестоимости продукции</a> либо отраслевыми версиями для <a href="/ru/calculators/leather-cost-calculator">кожевников</a> и <a href="/ru/calculators/cake-cost-calculator">кондитеров</a>.</p></div><hr><h2 id="архитектура-экрана-два-режима-работы" tabindex="-1">Архитектура экрана: Два режима работы <a class="header-anchor" href="#архитектура-экрана-два-режима-работы" aria-label="Permalink to &quot;Архитектура экрана: Два режима работы&quot;">​</a></h2><p>Интерфейс калькулятора разделен на два взаимосвязанных рабочих режима с помощью переключателя в верхней части рабочей области:</p><ol><li><strong>«Расчет тиража»</strong> — оперативный инструмент планирования производства. Вы выбираете готовое изделие из базы, задаете тираж выпуска, определяете вариант упаковки и мгновенно получаете детальную калькуляцию расходов с возможностью моментальной отправки партии в работу.</li><li><strong>«База рецептов»</strong> — конструктор и каталожный реестр технологических карт. Здесь создаются новые изделия, редактируются нормы списания материалов, настраиваются коэффициенты накладных расходов, публикуются товары на онлайн-витрине и ведется архив моделей.</li></ol><hr><h2 id="проектирование-технологическои-карты-конструктор-рецепта" tabindex="-1">Проектирование технологической карты (Конструктор рецепта) <a class="header-anchor" href="#проектирование-технологическои-карты-конструктор-рецепта" aria-label="Permalink to &quot;Проектирование технологической карты (Конструктор рецепта)&quot;">​</a></h2><p>Чтобы создать новую технологическую карту, перейдите в режим <strong>«База рецептов»</strong> и нажмите кнопку <strong>«Создать рецепт»</strong>. На экране откроется специализированный конструктор изделия.</p><h3 id="_1-базовые-реквизиты-изделия" tabindex="-1">1. Базовые реквизиты изделия <a class="header-anchor" href="#_1-базовые-реквизиты-изделия" aria-label="Permalink to &quot;1. Базовые реквизиты изделия&quot;">​</a></h3><ul><li><strong>Название изделия (рецепта):</strong> Полное наименование модели (например, <em>«Ремень классический из кожи буйвола (Шоколад)»</em>).</li><li><strong>Привязать к товару со склада (необязательно):</strong> Если номенклатурная позиция уже была предварительно создана на складе готовой продукции (вкладка «Товары»), Вы можете связать рецепт с существующей карточкой либо оставить значение по умолчанию — <em>«Создать новое изделие с нуля»</em>.</li><li><strong>«Модель изделия (линейка)»</strong> объединяет техкарты вариантов одного изделия. Выберите модель из списка или нажмите кнопку-карандаш, чтобы управлять справочником моделей (создавать, переименовывать и удалять). При выпуске готовая партия относится к изделию с выбранной моделью.</li><li><strong>Время работы (ч):</strong> Норма чистого времени квалифицированного мастера на изготовление одной единицы продукции (например, <code>1.5</code> часа). При расчете себестоимости программа перемножает эти трудозатраты на базовую часовую ставку из Настроек пространства с учетом персонального коэффициента сложности.</li></ul><hr><h2 id="трехсекционныи-состав-технологическои-карты" tabindex="-1">Трехсекционный состав технологической карты <a class="header-anchor" href="#трехсекционныи-состав-технологическои-карты" aria-label="Permalink to &quot;Трехсекционный состав технологической карты&quot;">​</a></h2><p>Конструктор рецепта объединяет производственную спецификацию, складскую тару и интернет-витрину в рамках трех специализированных вкладок:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"></span><div><strong>Вкладка «Сборка изделия»:</strong><br> Списание сырья и комплектующих на верстаке в момент выпуска тиража. </div></li><li><span class="craft-list-bullet"></span><div><strong>Вкладка «Сборка упаковки»:</strong><br> Отложенное списание тары, коробок и брендированных пакетов в момент реализации. </div></li><li><span class="craft-list-bullet"></span><div><strong>Вкладка «Витрина»:</strong><br> Параметры карточки товара, описания и публикация в онлайн-каталоге мастерской. </div></li></ul><h3 id="вкладка-1-«сборка-изделия»-материальная-спецификация" tabindex="-1">Вкладка 1: «Сборка изделия» (Материальная спецификация) <a class="header-anchor" href="#вкладка-1-«сборка-изделия»-материальная-спецификация" aria-label="Permalink to &quot;Вкладка 1: «Сборка изделия» (Материальная спецификация)&quot;">​</a></h3><p>В этой секции формируется перечень сырья и полуфабрикатов, которые физически расходуются при изготовлении изделия. Данные материалы безвозвратно списываются со склада в момент закрытия партии на Верстаке.</p><ol><li><strong>Категория сырья:</strong> Выпадающий список категорий позволяет мгновенно отфильтровать нужную номенклатуру (кожа, древесина, фурнитура, нити, клей).</li><li><strong>Складской материал:</strong> Выберите требуемую позицию из фактического складского наличия. Программа отобразит название и базовую единицу измерения.</li><li><strong>Норма расхода:</strong> Укажите физический расход на одну единицу изделия (<code>1.2</code> кв. дм, <code>3.5</code> пог. м, <code>4</code> шт.).</li><li>Нажмите кнопку <strong>«Добавить»</strong>. Позиция зафиксируется в производственной спецификации.</li></ol><div class="tip custom-block"><p class="custom-block-title">Совет мастера: Закладка технологического запаса на раскрой</p><p>При раскрое натурального массива древесины, листового металла или шорно-седельной кожи неизбежно образуются краевые обрезки, стружка и участки с природными дефектами сырья. Не закладывайте в рецепт геометрическую площадь заготовок «впритык». Всегда добавляйте технологический запас 10–20% к норме расхода, чтобы рассчитанная себестоимость полностью покрывала реальный расход закупленного материала.</p></div><h3 id="вкладка-2-«сборка-упаковки»-отложенное-списание-тары" tabindex="-1">Вкладка 2: «Сборка упаковки» (Отложенное списание тары) <a class="header-anchor" href="#вкладка-2-«сборка-упаковки»-отложенное-списание-тары" aria-label="Permalink to &quot;Вкладка 2: «Сборка упаковки» (Отложенное списание тары)&quot;">​</a></h3><p>В ремесленном деле упаковка играет двойную роль: она защищает товар при транспортировке и формирует премиальное восприятие бренда. Однако упаковочные материалы обладают принципиально иной логикой списания.</p><ul><li>Выберите комплект тары из выпадающего списка: стандартные наборы (<em>«Стандартная»</em>, <em>«Премиальная»</em>) либо создайте собственный формат через кнопку <strong>«Управление видами упаковки»</strong> (например, <em>«Деревянный пенал с ложементом»</em>).</li><li>Добавьте материалы упаковки со склада (крафтовая коробка, бумага тишью, бирка, пломба, сургуч) с указанием расхода на одну единицу.</li></ul><div class="info custom-block"><p class="custom-block-title">Физика учета: Почему упаковка не списывается на верстаке</p><p>Готовое изделие может храниться на складе готовой продукции неделями в ожидании покупателя. Если упаковать его сразу на верстаке, коробка рискует запылиться или помяться при хранении. Кроме того, один и тот же ремень покупатель может приобрести в базовом хлопковом чехле либо заказать в подарочном деревянном боксе. Поэтому упаковочные материалы <strong>не списываются при сборке на верстаке</strong>. Они бронируются в рецепте для расчета розничной цены, а физически списываются со склада строго в момент оформления продажи.</p></div><hr><h2 id="упаковка-и-фасовка-готовои-продукции" tabindex="-1">Упаковка и фасовка готовой продукции <a class="header-anchor" href="#упаковка-и-фасовка-готовои-продукции" aria-label="Permalink to &quot;Упаковка и фасовка готовой продукции&quot;">​</a></h2><p>Фасовка готовых изделий в фирменную тару — завершающий этап производственного цикла, напрямую влияющий на сохранность продукции и репутацию мастерской. В ОмниКрафт ЕРП реализован гибкий механизм учета тары, позволяющий привязывать к одной модели несколько видов упаковки и автоматически включать их стоимость в смету.</p><h3 id="цеховая-задача-и-раздельныи-учет-списания" tabindex="-1">Цеховая задача и раздельный учет списания <a class="header-anchor" href="#цеховая-задача-и-раздельныи-учет-списания" aria-label="Permalink to &quot;Цеховая задача и раздельный учет списания&quot;">​</a></h3><p>В отличие от сырья (кожи, дерева, металла, клея), которое безвозвратно перерабатывается мастером на верстаке, упаковочные материалы расходуются непосредственно перед передачей заказа покупателю или курьеру. Разделение списания решает три практические задачи цеха:</p><ol><li><strong>Защита тары от складского износа:</strong> изделия хранятся на складе в технологических чехлах без риска повреждения подарочных коробок.</li><li><strong>Вариативность комплектации:</strong> возможность продавать одно и то же изделие как в бюджетной крафтовой упаковке, так и в подарочном премиум-боксе.</li><li><strong>Точность финансовой себестоимости:</strong> стоимость коробок, наполнителя и лент учитывается в плановой цене тиража, но складской остаток списывается только по факту реализации.</li></ol><h3 id="предварительные-условия" tabindex="-1">Предварительные условия <a class="header-anchor" href="#предварительные-условия" aria-label="Permalink to &quot;Предварительные условия&quot;">​</a></h3><p>Перед настройкой комплектов упаковки в Калькуляторе выполните базовые действия:</p><ul><li>Оприходуйте упаковочные материалы на склад сырья через операцию «Партионная закупка» с категорией «Упаковка» (коробки, тишью, ленты, сургуч, фирменные бирки);</li><li>Убедитесь, что для каждой позиции заданы физические единицы измерения (штуки, метры, рулоны).</li></ul><h3 id="пошаговыи-порядок-заведения-тары-и-привязки-к-изделию" tabindex="-1">Пошаговый порядок заведения тары и привязки к изделию <a class="header-anchor" href="#пошаговыи-порядок-заведения-тары-и-привязки-к-изделию" aria-label="Permalink to &quot;Пошаговый порядок заведения тары и привязки к изделию&quot;">​</a></h3><ol><li><strong>Открытие окна видов упаковки:</strong> В конструкторе технологической карты перейдите на вкладку <strong>«Сборка упаковки»</strong> и нажмите кнопку с иконкой шестеренки <strong>«Управление видами упаковки»</strong> рядом с выпадающим списком комплектов.</li><li><strong>Создание нового вида тары:</strong> В модальном окне <strong>«Управление упаковками»</strong> введите наименование формата в поле <strong>«Название упаковки»</strong> (например, <em>«Деревянный пенал с гравировкой»</em>, <em>«Крафт-тубус премиум»</em>) и нажмите кнопку <strong>«Добавить»</strong>. Новый формат моментально появится в общем списке.</li><li><strong>Мягкое удаление неактуальных видов:</strong> При снятии типа тары с производства нажмите иконку корзины напротив строки. Тип упаковки архивируется без повреждения ранее оформленных расчетов. Для возврата в конструктор нажмите кнопку <strong>«Закрыть»</strong>.</li><li><strong>Комплектация набора материалами:</strong><ul><li>В конструкторе рецепта выберите созданный вид тары в списке <strong>«Упаковка»</strong>;</li><li>В выпадающем списке <strong>«Категория»</strong> выберите категорию складских материалов (например, <em>«Упаковка»</em>);</li><li>В списке <strong>«Упаковочный материал»</strong> выберите нужный складской артикул;</li><li>В поле <strong>«Количество»</strong> укажите расход на единицу готовой продукции;</li><li>Нажмите кнопку <strong>«Добавить»</strong>. Позиция отобразится в таблице упаковочного набора с указанием текущей складской себестоимости по методу МАК.</li></ul></li><li><strong>Включение упаковки в тираж и списание при продаже:</strong> В режиме <strong>«Расчет тиража»</strong> выберите нужную комплектацию в селекторе упаковки. Программа добавит стоимость тары в детализацию затрат партии. При продаже партии через Журнал продаж или Стол заказов программа автоматически спишет указанные упаковочные материалы со склада.</li></ol><div class="tip custom-block"><p class="custom-block-title">Вариативная упаковка под опт и розницу</p><p>Для одного рецепта можно настроить несколько независимых наборов тары. Например, вариант <em>«Оптовый»</em> включает только полиэтиленовый рукав и маркировочную бирку, а вариант <em>«Подарочный»</em> — крафтовую коробку, бумагу тишью и восковую печать. При расчете партии мастер моментально переключает комплектацию, видя объективную разницу в себестоимости.</p></div><h3 id="вкладка-3-«витрина»-своиства-онлаин-каталога" tabindex="-1">Вкладка 3: «Витрина» (Свойства онлайн-каталога) <a class="header-anchor" href="#вкладка-3-«витрина»-своиства-онлаин-каталога" aria-label="Permalink to &quot;Вкладка 3: «Витрина» (Свойства онлайн-каталога)&quot;">​</a></h3><p>Если Вы используете встроенный модуль публичной веб-витрины, карточку товара можно настроить непосредственно внутри конструктора техкарты без переходов в другие разделы:</p><ul><li><strong>Опубликовать на витрине:</strong> Главный переключатель видимости товара в публичном онлайн-магазине.</li><li><strong>Адрес страницы товара (ЧПУ-ссылка):</strong> Уникальный буквенный идентификатор страницы (например, <code>leather-belt-classic-brown</code>).</li><li><strong>Бейдж на сайте:</strong> Текстовая плашка для привлечения внимания покупателей (<em>«Хит продаж»</em>, <em>«Ручной шов»</em>, <em>«Ограниченный тираж»</em>).</li><li><strong>Цена для витрины:</strong> Фиксированная цена изделия при заказе через интернет-каталог.</li><li><strong>Описание для сайта:</strong> Текстовое поле с поддержкой форматирования Markdown для подробного описания потребительских свойств, габаритов, рекомендаций по уходу и состава материалов.</li></ul><hr><h2 id="настроика-ставки-наценки-и-накладных-расходов" tabindex="-1">Настройка ставки, наценки и накладных расходов <a class="header-anchor" href="#настроика-ставки-наценки-и-накладных-расходов" aria-label="Permalink to &quot;Настройка ставки, наценки и накладных расходов&quot;">​</a></h2><p>Косвенные затраты мастерской — амортизация оборудования, электроэнергия, аренда и расходники общего назначения — часто упускаются из виду. Кнопка <strong>«Настройка ставки, наценки и накладных расходов»</strong> открывает выдвижную панель персональной калибровки экономики изделия:</p><h3 id="_1-оплата-труда-и-целевая-норма-прибыли" tabindex="-1">1. Оплата труда и целевая норма прибыли <a class="header-anchor" href="#_1-оплата-труда-и-целевая-норма-прибыли" aria-label="Permalink to &quot;1. Оплата труда и целевая норма прибыли&quot;">​</a></h3><ul><li><strong>Почасовая ставка мастера:</strong> Индивидуальный коэффициент сложности труда. Если базовая системная ставка цеха составляет <code>800 руб./ч</code>, а данное изделие требует филигранного ручного тиснения, установите коэффициент <code>1.5</code> (эффективная ставка станет <code>1 200 руб./ч</code>). Для простой операции раскроя коэффициент можно снизить до <code>0.8</code>.</li><li><strong>Наценка на себестоимость:</strong> Персональный коэффициент к глобальной торговой наценке пространства. Позволяет гибко регулировать маржинальность конкретной модели.</li></ul><h3 id="_2-процентные-накладные-расходы" tabindex="-1">2. Процентные накладные расходы <a class="header-anchor" href="#_2-процентные-накладные-расходы" aria-label="Permalink to &quot;2. Процентные накладные расходы&quot;">​</a></h3><p>Программа извлекает список нормативных статей из глобальных Настроек пространства (износ станков, освещение, технический брак, мелкий расходный инструмент). Для каждого норматива доступен индивидуальный коэффициент:</p><ul><li>Для изделия, изготовленного исключительно ручным инструментом без включения станков, установите коэффициенту амортизации оборудования значение <code>0.0</code>.</li><li>Для сложного изделия с термической формовкой и полимеризацией коэффициент износа и энергозатрат можно повысить до <code>1.5</code>–<code>2.0</code>.</li></ul><h3 id="_3-фиксированные-накладные-расходы-на-единицу" tabindex="-1">3. Фиксированные накладные расходы на единицу <a class="header-anchor" href="#_3-фиксированные-накладные-расходы-на-единицу" aria-label="Permalink to &quot;3. Фиксированные накладные расходы на единицу&quot;">​</a></h3><p>Постоянные издержки, начисляемые на каждую выпущенную единицу продукции твердой суммой (сертификация партии, транспортные расходы по доставке заготовок на аутсорсинг, фиксированные бирки).</p><p>Система суммирует процентные и фиксированные составляющие в реальном времени, мгновенно выводя актуальный расчет на панели.</p><hr><h2 id="математическая-модель-расчета-себестоимости" tabindex="-1">Математическая модель расчета себестоимости <a class="header-anchor" href="#математическая-модель-расчета-себестоимости" aria-label="Permalink to &quot;Математическая модель расчета себестоимости&quot;">​</a></h2><p>ОмниКрафт ЕРП рассчитывает экономику изделия по объективной инженерной формуле, учитывающей прямые материальные затраты, стоимость труда и многоуровневые накладные расходы:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Калькуляция изделия</span><div class="formula-heading">Полная плановая себестоимость сборки единицы продукции</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Себестоимость единицы</span><span class="math-op">=</span><span class="math-var">Сырье (МАК)</span><span class="math-op">+</span><span class="math-var">Оплата труда</span><span class="math-op">+</span><span class="math-var">Накладные расходы</span><span class="math-op">+</span><span class="math-var">Упаковка</span></div></div></div><p>Где составляющие формулы формируются по строгим правилам учета:</p><ol><li><strong>Сырье изделия:</strong> Сумма произведений норм расхода на актуальную скользящую среднюю стоимость (МАК) каждого материала на складе в текущую секунду.</li><li><strong>Оплата труда:</strong> Произведение нормо-часов изделия на системную часовую ставку мастера и персональный коэффициент сложности.</li><li><strong>Накладные расходы:</strong> Сумма фиксированных затрат и процентной доли от базовой стоимости сырья и оплаты труда: <code>Накладные = Фиксированные расходы + (Сырье + Оплата труда) × (Сумма % / 100)</code>.</li><li><strong>Упаковка:</strong> Стоимость комплекта тары по текущим МАК-ценам складских остатков упаковочных материалов.</li></ol><div class="info custom-block"><p class="custom-block-title">Автоматическая синхронизация со складом через МАК</p><p>Вам не требуется пересчитывать техкарты вручную при каждом изменении цен поставщиков. Если новая партия кожи или металла поступила по более высокой цене, система автоматически пересчитает скользящую среднюю стоимость сырья на складе. В эту же секунду во всех рецептах отобразится обновленная объективная себестоимость.</p></div><hr><h2 id="расчет-тиража-и-запуск-партии-на-верстак" tabindex="-1">Расчет тиража и запуск партии на Верстак <a class="header-anchor" href="#расчет-тиража-и-запуск-партии-на-верстак" aria-label="Permalink to &quot;Расчет тиража и запуск партии на Верстак&quot;">​</a></h2><p>Когда база технологических карт сформирована, мастер переходит в режим оперативного расчета тиражей перед запуском производства.</p><ol><li><strong>Подбор изделия:</strong> Нажмите на поисковую строку <strong>«Найти рецепт изделия»</strong> и выберите требуемую модель из каталога активных техкарт.</li><li><strong>Указание тиража:</strong> В поле <strong>«Количество (шт)»</strong> введите запланированный объем партии (например, <code>10</code> штук).</li><li><strong>Выбор комплектации тары:</strong> В выпадающем списке <strong>«Упаковка»</strong> выберите нужный комплект либо оставьте вариант <em>«Без упаковки»</em>.</li><li><strong>Анализ сводки затрат:</strong> Блок «ДЕТАЛИЗАЦИЯ ЗАТРАТ НА ТИРАЖ» наглядно разложит полную финансовую смету партии: <ul><li>Затраты на сборку изделия (чистые материалы);</li><li>Фонд оплаты труда мастера с указанием общего объема нормо-часов;</li><li>Накладные расходы (процентные и фиксированные);</li><li>Комплектация упаковки;</li><li>Итоговая плановая себестоимость всей партии и себестоимость одной единицы.</li></ul></li><li><strong>Таблица компонентного состава:</strong> Программа выведет полную спецификацию партии с колонками: материал, общий требуемый расход, назначение (с цветовыми бейджами: синий — <strong>«Сборка изделия»</strong>, фиолетовый — <strong>«Упаковка: Название»</strong>) и сумма.</li></ol><div class="tip custom-block"><p class="custom-block-title">ИИ-анализ себестоимости и экономики партии</p><p>Рядом с заголовком детализации затрат расположена кнопка с иконкой искры. Нажатие на нее запускает интеллектуальный анализ тиража. ИИ-ассистент оценит соотношение затрат на материалы и ручной труд, проверит маржинальность при заданной наценке и выдаст прикладные рекомендации по оптимизации производственного бюджета.</p></div><hr><h2 id="контроль-обеспеченности-сырьем-и-постановка-в-план" tabindex="-1">Контроль обеспеченности сырьем и постановка в план <a class="header-anchor" href="#контроль-обеспеченности-сырьем-и-постановка-в-план" aria-label="Permalink to &quot;Контроль обеспеченности сырьем и постановка в план&quot;">​</a></h2><p>Убедившись в корректности расчетов, нажмите кнопку <strong>«Запустить в производство»</strong>. Система выполнит моментальную проверку складских остатков:</p><ul><li><strong>Материалов достаточно:</strong> Партия моментально создается и отправляется на вкладку <strong>«Верстак»</strong> в статус запланированных к сборке, а программа покажет подтверждающее уведомление.</li><li><strong>Обнаружен дефицит сырья:</strong> Программа откроет диалоговое предупреждение <strong>«Недостаточно материалов!»</strong>.</li></ul><p>В окне предупреждения система выведет точный перечень недостающих позиций с указанием требуемого количества и фактического доступного остатка:</p><div class="warning custom-block"><p class="custom-block-title">Перечень недостающего сырья</p><ul><li><strong>Кожа буйвола (Шоколад):</strong> требуется <code>12.0</code> кв. дм, доступно на складе <code>4.5</code> кв. дм;</li><li><strong>Вощеная нить 0.8 мм:</strong> требуется <code>35.0</code> пог. м, доступно на складе <code>10.0</code> пог. м.</li></ul></div><p>Мастер может выбрать один из двух вариантов действий:</p><ol><li><strong>«Отмена»:</strong> Отложить запуск партии до оформления закупки материалов на вкладке «Склад».</li><li><strong>«Да, запланировать»:</strong> Принудительно отправить партию на Верстак. Заказ появится в списке производственных заданий с отметкой об ожидании снабжения, что позволит мастеру не потерять задачу из вида.</li></ol><hr><h2 id="управление-базои-рецептов-отвязка-и-архив" tabindex="-1">Управление базой рецептов, отвязка и архив <a class="header-anchor" href="#управление-базои-рецептов-отвязка-и-архив" aria-label="Permalink to &quot;Управление базой рецептов, отвязка и архив&quot;">​</a></h2><p>В режиме <strong>«База рецептов»</strong> отображается удобный реестр технологических карт с пагинацией (по 25 позиций на страницу). В таблице сразу видна норма времени, процент накладных расходов и рассчитанная себестоимость единицы.</p><h3 id="редактирование-отвязка-и-архивация-техкарт" tabindex="-1">Редактирование, отвязка и архивация техкарт <a class="header-anchor" href="#редактирование-отвязка-и-архивация-техкарт" aria-label="Permalink to &quot;Редактирование, отвязка и архивация техкарт&quot;">​</a></h3><p>Для каждой активной строки таблицы доступен набор быстрых действий:</p><ul><li><strong>Редактировать (иконка карандаша):</strong> Открывает конструктор рецепта для корректировки норм расхода, времени или коэффициентов. Правки мгновенно применяются ко всем новым расчетам тиражей, но не меняют себестоимость ранее выпущенных изделий на складе готовой продукции.</li><li><strong>Удалить техкарту (иконка разорванной цепи):</strong> Позволяет отвязать технологическую карту от складского товара. При подтверждении операции техкарта удаляется из Калькулятора, однако сам товар и его остатки полностью сохраняются на складе готовой продукции. Это полезно, если Вы прекращаете самостоятельный пошив модели, но планируете продавать оставшиеся на складе складские запасы.</li><li><strong>Отправить в архив (иконка коробки):</strong> Переносит технологическую карту в архивное хранилище. Модель скрывается из выпадающих списков расчета тиражей, освобождая рабочее пространство от неактуальных позиций.</li></ul><div class="warning custom-block"><p class="custom-block-title">Защита от производственного сбоя: Блокировка архивации</p><p>Программа аппаратно заблокирует отправку рецепта в архив, если прямо сейчас на Верстаке находится незавершенная партия этого изделия. Перед архивацией техкарты необходимо выпустить готовую продукцию либо отменить производственное задание на верстаке.</p></div><h3 id="работа-с-архивными-техкартами" tabindex="-1">Работа с архивными техкартами <a class="header-anchor" href="#работа-с-архивными-техкартами" aria-label="Permalink to &quot;Работа с архивными техкартами&quot;">​</a></h3><p>С помощью переключателя в правом верхнем углу таблицы перейдите в список <strong>«Архивные»</strong>:</p><ul><li><strong>Восстановить (иконка со стрелкой):</strong> Моментально возвращает технологическую карту в основной рабочий каталог со всеми сохраненными нормами расхода и финансовыми настройками.</li><li><strong>Удалить навсегда (иконка корзины):</strong> Полное стирание карточки из базы данных. Данное действие разрешено только в том случае, если физический остаток товара на складе готовой продукции равен нулю. При наличии остатков система потребует сначала списать их через инвентаризацию во вкладке «Товары».</li></ul><hr><h2 id="смежные-разделы-и-сквозная-навигация" tabindex="-1">Смежные разделы и сквозная навигация <a class="header-anchor" href="#смежные-разделы-и-сквозная-навигация" aria-label="Permalink to &quot;Смежные разделы и сквозная навигация&quot;">​</a></h2><ul><li><a href="/ru/docs/spaces/production/cycle">Производственный цикл</a> — сквозной пошаговый маршрут от закупки сырья до выдачи чека.</li><li><a href="/ru/docs/spaces/production/workbench">Верстак мастерской</a> — диспетчеризация партий в работе, списание материалов и выпуск продукции.</li><li><a href="/ru/docs/spaces/production/showcase">Склад готовых товаров</a> — партии готовых изделий, партионный учет методом первых партий (ФИФО) и складская стоимость.</li><li><a href="/ru/docs/resources/warehouse">Управление запасами сырья</a> — приходные накладные, распределение доставки и складские остатки.</li></ul>',83))])}const v=s(d,[["render",h]]);export{k as __pageData,v as default};
